param([Parameter(Mandatory=$true)][string]$SourcePath,[Parameter(Mandatory=$true)][string]$HeaderPath,[Parameter(Mandatory=$true)][string]$TestPath,[Parameter(Mandatory=$true)][string]$HypervisorCMake,[Parameter(Mandatory=$true)][string]$TestsCMake,[Parameter(Mandatory=$true)][string]$ForbiddenPaths)
$ErrorActionPreference='Stop';function A($x,$m){if(-not$x){throw $m}};function O($t,$a,$n){$p=-1;foreach($x in $a){$q=$t.IndexOf($x,$p+1);A($q-gt$p)"$n $x";$p=$q}}
function B($t,$a,$b){$i=$t.IndexOf($a);$j=$t.IndexOf($b,$i+$a.Length);A($i-ge0-and$j-gt$i)"section $a";$t.Substring($i,$j-$i)}
function V($s,$h,$t,$hc,$tc){
 foreach($x in @('VmxCr3RouteOwnerValidateBinding(','reads mutable residency slots','VmxCr3RouteOwnerValidate(','VmxCr3RouteOwnerSnapshot(','coherent target set','try-locked independently','contention returns BUSY','corruption returns','Either failure clears','VmxCr3RouteOwnerInitialize(','VmxCr3RouteOwnerInitializeGuarded(','stable caller-owned state','VmxCr3RouteOwnerPlan(','VmxCr3RouteOwnerCommit(','VmxCr3RouteOwnerReset(','Call only after all planned VMCS writes succeed')){A($h.Contains($x))"header $x"}
 A($s.Contains('return CoreValid(Owner) ? VMX_CR3_TARGET_OK : VMX_CR3_TARGET_INVALID;'))'binding validation';
 foreach($x in @('TryLock','_InterlockedCompareExchange((volatile long*)Busy, 1, 0) == 0','Unlock','_InterlockedExchange((volatile long*)Busy, 0)','CoreValid','State->Busy != 0','State->Reserved32 != 0','SnapshotState','CopyState','PublishState')){A($s.Contains($x))"source $x"}
 $core=B $s 'static int CoreValid' 'static VMX_CR3_TARGET_STATUS SnapshotState';A($core-notmatch 'for \(')'core does not scan mutable states'
 $snapshot=B $s 'VMX_CR3_TARGET_STATUS VmxCr3RouteOwnerSnapshot' 'VMX_CR3_TARGET_STATUS VmxCr3RouteOwnerInitialize'
 O $snapshot @('CoreValid(Owner)','StateCapacity != Owner->Count','!Zero(OutTargetSet','!Zero(OutStates','Separate(Owner','Separate(Owner->States','Separate(OutTargetSet','SnapshotState(Owner, Index','memset(OutStates, 0, Bytes)','return Status','*OutTargetSet = Owner->TargetSet') 'snapshot'
 $plan=B $s 'VMX_CR3_TARGET_STATUS VmxCr3RouteOwnerPlan' 'VMX_CR3_TARGET_STATUS VmxCr3RouteOwnerCommit'
 O $plan @('CoreValid(Owner)','ProcessorIndex >= Owner->Count','SnapshotState(Owner, ProcessorIndex, &Previous)','VmxCr3RoutePlanBuildTargetState(&Owner->TargetSet, &Previous','TargetEnabled(Owner)') 'plan'
 $commit=B $s 'VMX_CR3_TARGET_STATUS VmxCr3RouteOwnerCommit' 'VMX_CR3_TARGET_STATUS VmxCr3RouteOwnerReset'
 O $commit @('CoreValid(Owner)','State = &Owner->States[ProcessorIndex]','TryLock(&State->Busy)','CopyState(State, &Previous)','StateValid(Owner, &Previous)','VmxCr3TargetSelect','VmxCr3ResidencyApply(&Previous','DisabledTarget.Matched = 0','VmxCr3ResidencyApply(&Previous','memcmp(&Expected, &Plan->Transition','memcmp(&DisabledExpected, &Plan->Transition','TargetEnabled(Owner)','Expected = DisabledExpected','PublishState(State, &Expected.Next)','Unlock(&State->Busy)','return Status') 'commit'
 A(([regex]::Matches($commit,'TryLock\(&State->Busy\)')).Count-eq1-and([regex]::Matches($commit,'Unlock\(&State->Busy\)')).Count-eq1)'commit exact lock'
 foreach($x in @('coherent snapshot','snapshot exact per processor state','busy snapshot rejected','busy snapshot clears outputs','stale plan rejected','reset zeroes owner and states','guarded owner initialize','expired guard remains outside','expired guard cannot publish residency','expiry race cannot publish residency')){A($t.Contains($x))"test $x"}
 A($s-notmatch '(?i)ntddk|wdm\.h|wdf\.h|__vmx|vmread|vmwrite|invept|IOCTL|Dispatcher')'pure';A(([regex]::Matches($hc,'(?m)^\s*vmx_cr3_route_owner\.c\s*$')).Count-eq1)'source once';A(([regex]::Matches($tc,'test_vmx_cr3_route_owner_contracts')).Count-eq1)'contract once'
}
$s=Get-Content -Raw $SourcePath;$h=Get-Content -Raw $HeaderPath;$t=Get-Content -Raw $TestPath;$hc=Get-Content -Raw $HypervisorCMake;$tc=Get-Content -Raw $TestsCMake;V $s $h $t $hc $tc;foreach($p in $ForbiddenPaths.Split(',')){A((Get-Content -Raw $p)-notmatch 'VmxCr3RouteOwner|vmx_cr3_route_owner')"unwired $p"}
$m=@($s.Replace('_InterlockedCompareExchange((volatile long*)Busy, 1, 0)','_InterlockedCompareExchange((volatile long*)Busy, 0, 0)'),$s.Replace('State->Busy != 0','0'),$s.Replace('VMX_CR3_TARGET_STATUS Status = SnapshotState','VMX_CR3_TARGET_STATUS Status = VMX_CR3_TARGET_OK; /* removed */'),$s.Replace('memset(OutStates, 0, Bytes);',''),$s.Replace('SnapshotState(Owner, ProcessorIndex, &Previous)','SnapshotState(Owner, 0, &Previous)'),$s.Replace('TryLock(&State->Busy)','1'),$s.Replace('VmxCr3ResidencyApply(&Previous','VmxCr3ResidencyApply(&Owner->States[ProcessorIndex]'),$s.Replace('PublishState(State, &Expected.Next)','PublishState(&Owner->States[0], &Expected.Next)'),$s.Replace('Unlock(&State->Busy)','Unlock(&Owner->States[0].Busy)'),$s.Replace('if (!TargetEnabled(Owner))','if (0)'));$i=0;foreach($x in $m){$i++;A($x-ne$s)"vacuous $i";$bad=$false;try{V $x $h $t $hc $tc}catch{$bad=$true};A($bad)"accepted $i"}
Write-Host 'PASS: the CR3 route owner isolates mutable per-CPU slots with try-lock publication, snapshots coherently, and plans/commits only the selected processor state.'
